   300→      const blockInput = chain.seenBlockInputCache.get(blockRootHex);
   301→      if (blockInput && isBlockInputColumns(blockInput) && blockInput.hasColumn(dataColumnSidecar.index)) {
   302→        metrics?.peerDas.dataColumnSidecarProcessingSkip.inc();
   303→        logger.debug("Already have column sidecar, skipping processing", {
   304→          ...blockInput.getLogMeta(),
   305→          index: dataColumnSidecar.index,
   306→        });
   307→        return blockInput;
   308→      }
   309→    }
   310→
   311→    const verificationTimer = metrics?.peerDas.dataColumnSidecarGossipVerificationTime.startTimer();
   312→
   313→    const delaySec = chain.clock.secFromSlot(slot, seenTimestampSec);
   314→    const recvToValLatency = Date.now() / 1000 - seenTimestampSec;
   315→
   316→    try {
   317→      await validateGossipDataColumnSidecar(chain, dataColumnSidecar, gossipSubnet, metrics);
   318→      const blockInput = chain.seenBlockInputCache.getByColumn({
   319→        blockRootHex,
   320→        columnSidecar: dataColumnSidecar,
   321→        source: BlockInputSource.gossip,
   322→        seenTimestampSec,
   323→        peerIdStr,
   324→      });
   325→
   326→      const recvToValidation = Date.now() / 1000 - seenTimestampSec;
   327→      const validationTime = recvToValidation - recvToValLatency;
   328→
   329→      metrics?.peerDas.dataColumnSidecarProcessingSuccesses.inc();
   330→      metrics?.gossipBlob.recvToValidation.observe(recvToValidation);
   331→      metrics?.gossipBlob.validationTime.observe(validationTime);
   332→
   333→      if (chain.emitter.listenerCount(routes.events.EventType.dataColumnSidecar)) {
   334→        chain.emitter.emit(routes.events.EventType.dataColumnSidecar, {
   335→          blockRoot: blockRootHex,
   336→          slot,
   337→          index: dataColumnSidecar.index,
   338→          kzgCommitments: dataColumnSidecar.kzgCommitments.map(toHex),
   339→        });
   340→      }
   341→
   342→      logger.debug("Received gossip dataColumn", {
   343→        ...blockInput.getLogMeta(),
   344→        currentSlot: chain.clock.currentSlot,
   345→        peerId: peerIdStr,
   346→        delaySec,
   347→        gossipSubnet,
   348→        columnIndex: dataColumnSidecar.index,
   349→        recvToValLatency,
   350→        recvToValidation,
   351→        validationTime,
   352→      });
   353→
   354→      return blockInput;
   355→    } catch (e) {
   356→      if (e instanceof DataColumnSidecarGossipError && e.action === GossipAction.REJECT) {
   357→        chain.persistInvalidSszValue(
   358→          ssz.fulu.DataColumnSidecar,
   359→          dataColumnSidecar,
   360→          `gossip_reject_slot_${slot}_index_${dataColumnSidecar.index}`
   361→        );
   362→        // no need to trigger `unknownBlockParent` event here, as we already did it in `validateBeaconBlock()`
   363→        //
   364→        // TODO(fulu): is this note above correct? Could have random column that we see that could trigger
   365→        //        unknownBlockSync.  And duplicate addition of a block will be deduplicated by the
   366→        //        BlockInputSync event handler. Check this!!
   367→        // events.emit(NetworkEvent.unknownBlockParent, {blockInput, peer: peerIdStr});
   368→      }
   369→
   370→      throw e;
   371→    } finally {
   372→      verificationTimer?.();
   373→    }
   374→  }
   375→
   376→  function handleValidBeaconBlock(blockInput: IBlockInput, peerIdStr: string, seenTimestampSec: number): void {
   377→    const signedBlock = blockInput.getBlock();
   378→    const slot = signedBlock.message.slot;
   379→
   380→    // Handler - MUST NOT `await`, to allow validation result to be propagated
   381→
   382→    const delaySec = seenTimestampSec - computeTimeAtSlot(config, slot, chain.genesisTime);
   383→    metrics?.gossipBlock.elapsedTimeTillReceived.observe({source: OpSource.gossip}, delaySec);
   384→    chain.validatorMonitor?.registerBeaconBlock(OpSource.gossip, delaySec, signedBlock.message);
   385→    if (!blockInput.hasBlockAndAllData()) {
   386→      chain.logger.debug("Received gossip block, attempting fetch of unavailable data", blockInput.getLogMeta());
   387→      // The data is not yet fully available, immediately trigger an aggressive pull via unknown block sync
   388→      chain.emitter.emit(ChainEvent.incompleteBlockInput, {
   389→        blockInput,
   390→        peer: peerIdStr,
   391→        source: BlockInputSource.gossip,
   392→      });
   393→      // immediately attempt fetch of data columns from execution engine
   394→      chain.getBlobsTracker.triggerGetBlobs(blockInput);
   395→    } else {
   396→      metrics?.blockInputFetchStats.totalDataAvailableBlockInputs.inc();
   397→      metrics?.blockInputFetchStats.totalDataAvailableBlockInputBlobs.inc(
   398→        (signedBlock.message as deneb.BeaconBlock).body.blobKzgCommitments.length
   399→      );
   400→    }
   401→
   402→    chain
   403→      .processBlock(blockInput, {
   404→        // block may be downloaded and processed by UnknownBlockSync
   405→        ignoreIfKnown: true,
   406→        // proposer signature already checked in validateBeaconBlock()
   407→        validProposerSignature: true,
   408→        // blobSidecars already checked in validateGossipBlobSidecars()
   409→        validBlobSidecars: BlobSidecarValidation.Individual,
   410→        // It's critical to keep a good number of mesh peers.
   411→        // To do that, the Gossip Job Wait Time should be consistently <3s to avoid the behavior penalties in gossip
   412→        // Gossip Job Wait Time depends on the BLS Job Wait Time
   413→        // so `blsVerifyOnMainThread = true`: we want to verify signatures immediately without affecting the bls thread pool.
   414→        // otherwise we can't utilize bls thread pool capacity and Gossip Job Wait Time can't be kept low consistently.
   415→        // See https://github.com/ChainSafe/lodestar/issues/3792
   416→        blsVerifyOnMainThread: true,
   417→        // to track block process steps
   418→        seenTimestampSec,
   419→        // gossip block is validated, we want to process it asap
   420→        eagerPersistBlock: true,
   421→      })
   422→      .then(() => {
   423→        // Returns the delay between the start of `block.slot` and `current time`
   424→        const delaySec = chain.clock.secFromSlot(slot);
   425→        metrics?.gossipBlock.elapsedTimeTillProcessed.observe(delaySec);
   426→        chain.seenBlockInputCache.prune(blockInput.blockRootHex);
   427→      })
   428→      .catch((e) => {
   429→        // Adjust verbosity based on error type
   430→        let logLevel: LogLevel;
   431→
   432→        if (e instanceof BlockError) {
   433→          switch (e.type.code) {
   434→            case BlockErrorCode.DATA_UNAVAILABLE: {
   435→              // Error is quite frequent and not critical
   436→              logLevel = LogLevel.debug;
   437→              break;
   438→            }
   439→            // ALREADY_KNOWN should not happen with ignoreIfKnown=true above
   440→            // PARENT_UNKNOWN should not happen, we handled this in validateBeaconBlock() function above
   441→            case BlockErrorCode.ALREADY_KNOWN:
   442→            case BlockErrorCode.PARENT_UNKNOWN:
   443→            case BlockErrorCode.PRESTATE_MISSING:
   444→            case BlockErrorCode.EXECUTION_ENGINE_ERROR:
   445→              // Errors might indicate an issue with our node or the connected EL client
   446→              logLevel = LogLevel.error;
   447→              break;
   448→            default:
   449→              // TODO: Should it use PeerId or string?
   450→              core.reportPeer(peerIdStr, PeerAction.LowToleranceError, "BadGossipBlock");
   451→              // Misbehaving peer, but could highlight an issue in another client
   452→              logLevel = LogLevel.warn;
   453→          }
   454→        } else {
   455→          // Any unexpected error
   456→          logLevel = LogLevel.error;
   457→        }
   458→        metrics?.gossipBlock.processBlockErrors.inc({error: e instanceof BlockError ? e.type.code : "NOT_BLOCK_ERROR"});
   459→        logger[logLevel](
   460→          "Error processing block",
   461→          {slot, peer: peerIdStr, blockRoot: prettyBytes(blockInput.blockRootHex)},
   462→          e as Error
   463→        );
   464→        // TODO(fulu): Revisit when we prune block inputs
   465→        chain.seenBlockInputCache.prune(blockInput.blockRootHex);
   466→      });
   467→  }
   468→
   469→  return {
   470→    [GossipType.beacon_block]: async ({
   471→      gossipData,
   472→      topic,
   473→      peerIdStr,
   474→      seenTimestampSec,
   475→    }: GossipHandlerParamGeneric<GossipType.beacon_block>) => {
   476→      const {serializedData} = gossipData;
   477→
   478→      const signedBlock = sszDeserialize(topic, serializedData);
   479→      const blockInput = await validateBeaconBlock(signedBlock, topic.boundary.fork, peerIdStr, seenTimestampSec);
   480→      chain.serializedCache.set(signedBlock, serializedData);
   481→      handleValidBeaconBlock(blockInput, peerIdStr, seenTimestampSec);
   482→    },
   483→
   484→    [GossipType.blob_sidecar]: async ({
   485→      gossipData,
   486→      topic,
   487→      peerIdStr,
   488→      seenTimestampSec,
   489→    }: GossipHandlerParamGeneric<GossipType.blob_sidecar>) => {
   490→      const {serializedData} = gossipData;
   491→      const blobSidecar = sszDeserialize(topic, serializedData);
   492→      const blobSlot = blobSidecar.signedBlockHeader.message.slot;
   493→      const index = blobSidecar.index;
   494→
   495→      if (config.getForkSeq(blobSlot) < ForkSeq.deneb) {
   496→        throw new GossipActionError(GossipAction.REJECT, {code: "PRE_DENEB_BLOCK"});
   497→      }
   498→      const blockInput = await validateBeaconBlob(blobSidecar, topic.subnet, peerIdStr, seenTimestampSec);
   499→      if (!blockInput.hasBlockAndAllData()) {
   500→        const cutoffTimeMs = getCutoffTimeMs(chain, blobSlot, BLOCK_AVAILABILITY_CUTOFF_MS);
   501→        chain.logger.debug("Received gossip blob, waiting for full data availability", {
   502→          msToWait: cutoffTimeMs,
   503→          blobIndex: index,
   504→          ...blockInput.getLogMeta(),
   505→        });
   506→        blockInput.waitForAllData(cutoffTimeMs).catch((_e) => {
   507→          chain.logger.debug(
   508→            "Waited for data after receiving gossip blob. Cut-off reached so attempting to fetch remainder of BlockInput",
   509→            {
   510→              blobIndex: index,
   511→              ...blockInput.getLogMeta(),
   512→            }
   513→          );
   514→          chain.emitter.emit(ChainEvent.incompleteBlockInput, {
   515→            blockInput,
   516→            peer: peerIdStr,
   517→            source: BlockInputSource.gossip,
   518→          });
   519→        });
   520→      }
   521→    },
   522→
   523→    [GossipType.data_column_sidecar]: async ({
   524→      gossipData,
   525→      topic,
   526→      peerIdStr,
   527→      seenTimestampSec,
   528→    }: GossipHandlerParamGeneric<GossipType.data_column_sidecar>) => {
   529→      const {serializedData} = gossipData;
   530→      const dataColumnSidecar = sszDeserialize(topic, serializedData);
   531→      const dataColumnSlot = dataColumnSidecar.signedBlockHeader.message.slot;
   532→      const index = dataColumnSidecar.index;
   533→
   534→      if (config.getForkSeq(dataColumnSlot) < ForkSeq.fulu) {
   535→        throw new GossipActionError(GossipAction.REJECT, {code: "PRE_FULU_BLOCK"});
   536→      }
   537→      const delaySec = chain.clock.secFromSlot(dataColumnSlot, seenTimestampSec);
   538→      const blockInput = await validateBeaconDataColumn(
   539→        dataColumnSidecar,
   540→        serializedData,
   541→        topic.subnet,
   542→        peerIdStr,
   543→        seenTimestampSec
   544→      );
   545→      const blockInputMeta = blockInput.getLogMeta();
   546→      const {receivedColumns} = blockInputMeta;
   547→      // it's not helpful to track every single column received
   548→      // instead of that, track 1st, 8th, 16th 32th, 64th, and 128th column
   549→      switch (receivedColumns) {
   550→        case 1:
   551→        case config.SAMPLES_PER_SLOT:
   552→        case 2 * config.SAMPLES_PER_SLOT:
   553→        case NUMBER_OF_COLUMNS / 4:
   554→        case NUMBER_OF_COLUMNS / 2:
   555→        case NUMBER_OF_COLUMNS:
   556→          metrics?.dataColumns.elapsedTimeTillReceived.observe({receivedOrder: receivedColumns}, delaySec);
   557→          break;
   558→      }
   559→      if (!blockInput.hasBlockAndAllData()) {
   560→        const cutoffTimeMs = getCutoffTimeMs(chain, dataColumnSlot, BLOCK_AVAILABILITY_CUTOFF_MS);
   561→        chain.logger.debug("Received gossip data column, waiting for full data availability", {
   562→          msToWait: cutoffTimeMs,
   563→          dataColumnIndex: index,
   564→          ...blockInputMeta,
   565→        });
   566→        // do not await here to not delay gossip validation
   567→        blockInput.waitForBlockAndAllData(cutoffTimeMs).catch((_e) => {
   568→          chain.logger.debug(
   569→            "Waited for data after receiving gossip column. Cut-off reached so attempting to fetch remainder of BlockInput",
   570→            {
   571→              dataColumnIndex: index,
   572→              ...blockInputMeta,
   573→            }
   574→          );
   575→          chain.emitter.emit(ChainEvent.incompleteBlockInput, {
   576→            blockInput,
   577→            peer: peerIdStr,
   578→            source: BlockInputSource.gossip,
   579→          });
   580→        });
   581→        // immediately attempt fetch of data columns from execution engine
   582→        chain.getBlobsTracker.triggerGetBlobs(blockInput);
   583→        // if we've received at least half of the columns, trigger reconstruction of the rest
   584→        if (blockInput.columnCount >= NUMBER_OF_COLUMNS / 2) {
   585→          chain.columnReconstructionTracker.triggerColumnReconstruction(blockInput);
   586→        }
   587→      }
   588→    },
   589→
   590→    [GossipType.beacon_aggregate_and_proof]: async ({
   591→      gossipData,
   592→      topic,
   593→      seenTimestampSec,
   594→    }: GossipHandlerParamGeneric<GossipType.beacon_aggregate_and_proof>) => {
   595→      const {serializedData} = gossipData;
   596→      let validationResult: AggregateAndProofValidationResult;
   597→      const signedAggregateAndProof = sszDeserialize(topic, serializedData);
   598→      const {fork} = topic.boundary;
   599→
   600→      try {
   601→        validationResult = await validateGossipAggregateAndProof(fork, chain, signedAggregateAndProof, serializedData);
   602→      } catch (e) {
   603→        if (e instanceof AttestationError && e.action === GossipAction.REJECT) {
   604→          chain.persistInvalidSszValue(
   605→            sszTypesFor(fork).SignedAggregateAndProof,
   606→            signedAggregateAndProof,
   607→            "gossip_reject"
   608→          );
   609→        }
   610→        throw e;
   611→      }
   612→
   613→      // Handler
   614→      const {indexedAttestation, committeeValidatorIndices, attDataRootHex} = validationResult;
   615→      chain.validatorMonitor?.registerGossipAggregatedAttestation(
   616→        seenTimestampSec,
   617→        signedAggregateAndProof,
   618→        indexedAttestation
   619→      );
   620→      const aggregatedAttestation = signedAggregateAndProof.message.aggregate;
   621→
   622→      const insertOutcome = chain.aggregatedAttestationPool.add(
