   798→/**
   799→ * For now, only beacon_attestation topic is batched.
   800→ */
   801→function getBatchHandlers(modules: ValidatorFnsModules, options: GossipHandlerOpts): BatchGossipHandlers {
   802→  const {chain, metrics, logger, aggregatorTracker} = modules;
   803→  return {
   804→    [GossipType.beacon_attestation]: async (
   805→      gossipHandlerParams: GossipHandlerParamGeneric<GossipType.beacon_attestation>[]
   806→    ): Promise<(null | AttestationError)[]> => {
   807→      const results: (null | AttestationError)[] = [];
   808→      const attestationCount = gossipHandlerParams.length;
   809→      if (attestationCount === 0) {
   810→        return results;
   811→      }
   812→      // all attestations should have same attestation data as filtered by network processor
   813→      const {fork} = gossipHandlerParams[0].topic.boundary;
   814→      const validationParams = gossipHandlerParams.map((param) => ({
   815→        attestation: null,
   816→        serializedData: param.gossipData.serializedData,
   817→        attSlot: param.gossipData.msgSlot,
   818→        attDataBase64: param.gossipData.indexed,
   819→        subnet: param.topic.subnet,
   820→      })) as GossipAttestation[];
   821→      const {results: validationResults, batchableBls} = await validateGossipAttestationsSameAttData(
   822→        fork,
   823→        chain,
   824→        validationParams
   825→      );
   826→      for (const [i, validationResult] of validationResults.entries()) {
   827→        if (validationResult.err) {
   828→          results.push(validationResult.err as AttestationError);
   829→          continue;
   830→        }
   831→        // null means no error
   832→        results.push(null);
   833→
   834→        // Handler
   835→        const {
   836→          indexedAttestation,
   837→          attDataRootHex,
   838→          attestation,
   839→          committeeIndex,
   840→          validatorCommitteeIndex,
   841→          committeeSize,
   842→        } = validationResult.result;
   843→        chain.validatorMonitor?.registerGossipUnaggregatedAttestation(
   844→          gossipHandlerParams[i].seenTimestampSec,
   845→          indexedAttestation
   846→        );
   847→
   848→        const {subnet} = validationResult.result;
   849→        try {
   850→          // Node may be subscribe to extra subnets (long-lived random subnets). For those, validate the messages
   851→          // but don't add to attestation pool, to save CPU and RAM
   852→          if (aggregatorTracker.shouldAggregate(subnet, indexedAttestation.data.slot)) {
   853→            const insertOutcome = chain.attestationPool.add(
   854→              committeeIndex,
   855→              attestation,
   856→              attDataRootHex,
   857→              validatorCommitteeIndex,
   858→              committeeSize
   859→            );
   860→            metrics?.opPool.attestationPool.gossipInsertOutcome.inc({insertOutcome});
   861→          }
   862→        } catch (e) {
   863→          logger.error("Error adding unaggregated attestation to pool", {subnet}, e as Error);
   864→        }
   865→
   866→        if (!options.dontSendGossipAttestationsToForkchoice) {
   867→          try {
   868→            chain.forkChoice.onAttestation(indexedAttestation, attDataRootHex);
   869→          } catch (e) {
   870→            logger.debug("Error adding gossip unaggregated attestation to forkchoice", {subnet}, e as Error);
   871→          }
   872→        }
   873→
   874→        if (isForkPostElectra(fork)) {
   875→          chain.emitter.emit(
   876→            routes.events.EventType.singleAttestation,
   877→            attestation as SingleAttestation<ForkPostElectra>
   878→          );
   879→        } else {
   880→          chain.emitter.emit(routes.events.EventType.attestation, attestation as SingleAttestation<ForkPreElectra>);
   881→          chain.emitter.emit(
   882→            routes.events.EventType.singleAttestation,
   883→            toElectraSingleAttestation(
   884→              attestation as SingleAttestation<ForkPreElectra>,
   885→              indexedAttestation.attestingIndices[0]
   886→            )
   887→          );
   888→        }
   889→      }
   890→
   891→      if (batchableBls) {
   892→        metrics?.gossipAttestation.attestationBatchHistogram.observe(attestationCount);
   893→      } else {
   894→        metrics?.gossipAttestation.attestationNonBatchCount.inc(attestationCount);
   895→      }
   896→
   897→      return results;
   898→    },
   899→  };
   900→}
   901→
   902→/**
   903→ * Retry a function if it throws error code UNKNOWN_OR_PREFINALIZED_BEACON_BLOCK_ROOT
   904→ */
   905→export async function validateGossipFnRetryUnknownRoot<T>(
   906→  fn: () => Promise<T>,
   907→  network: INetwork,
   908→  chain: IBeaconChain,
   909→  slot: Slot,
   910→  blockRoot: Root
   911→): Promise<T> {
   912→  let unknownBlockRootRetries = 0;
   913→  while (true) {
   914→    try {
   915→      return await fn();
   916→    } catch (e) {
   917→      if (
   918→        e instanceof AttestationError &&
   919→        e.type.code === AttestationErrorCode.UNKNOWN_OR_PREFINALIZED_BEACON_BLOCK_ROOT
   920→      ) {
   921→        if (unknownBlockRootRetries === 0) {
   922→          // Trigger unknown block root search here
   923→          const rootHex = toRootHex(blockRoot);
   924→          network.searchUnknownSlotRoot({slot, root: rootHex}, BlockInputSource.gossip);
   925→        }
   926→
   927→        if (unknownBlockRootRetries++ < MAX_UNKNOWN_BLOCK_ROOT_RETRIES) {
   928→          const foundBlock = await chain.waitForBlock(slot, toRootHex(blockRoot));
   929→          // Returns true if the block was found on time. In that case, try to get it from the fork-choice again.
   930→          // Otherwise, throw the error below.
   931→          if (foundBlock) {
   932→            continue;
   933→          }
   934→        }
   935→      }
   936→
   937→      throw e;
   938→    }
   939→  }
   940→}
   941→
   942→function getCutoffTimeMs(
   943→  chain: {config: ChainForkConfig; genesisTime: UintNum64; logger: Logger},
   944→  blockSlot: Slot,
   945→  cutoffMsFromSlotStart: number
   946→): number {
   947→  return Math.max(
   948→    computeTimeAtSlot(chain.config, blockSlot, chain.genesisTime) * 1000 + cutoffMsFromSlotStart - Date.now(),
   949→    0
   950→  );
   951→}
